package com.reps.demogcloud.security.services;
import com.reps.demogcloud.security.models.*;
import com.reps.demogcloud.services.*;
import com.reps.demogcloud.services.email.EmailSenderService;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.data.mongodb.core.*;
import org.springframework.data.mongodb.core.query.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.mail.MailAuthenticationException;
import java.time.Instant;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.junit.jupiter.api.Assertions.*;
class AccountAccessServiceTest {
 UserRepository users; MongoTemplate mongo; PasswordEncoder encoder; EmailSenderService mail; MockEnvironment env;
 AccountAccessService service; UserModel user;
 @BeforeEach void setup(){users=mock(UserRepository.class);mongo=mock(MongoTemplate.class);encoder=mock(PasswordEncoder.class);mail=mock(EmailSenderService.class);env=new MockEnvironment().withProperty("reps.accounts.public-base-url","https://repsdev.vercel.app");service=new AccountAccessService(users,mongo,encoder,mail,env,mock(WorkflowAccessService.class),mock(UserContextService.class));user=new UserModel();user.setId("synthetic-id");user.setUsername("student@example.test");user.setSchool("Testing");user.setPassword("old-encoded");when(users.findByUsername(user.getUsername())).thenReturn(user);when(encoder.encode(anyString())).thenReturn("new-encoded");}
 void ticket(String credential,String purpose){var t=new UserModel.AccessTicket();t.setDigest(AccountAccessService.digest(credential));t.setPurpose(purpose);t.setIssueId("synthetic-issue");t.setEnvironment("https://repsdev.vercel.app");t.setAttempts(5);t.setExpiresAt(Instant.now().plusSeconds(600));user.setAccessTicket(t);when(mongo.findOne(any(Query.class),eq(UserModel.class))).thenReturn(user);}
 @Test void completionAtomicallyConsumesAndChangesOnlyCredentialFields(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");when(mongo.findAndModify(any(),any(),any(FindAndModifyOptions.class),eq(UserModel.class))).thenReturn(user).thenReturn(null);service.complete(user.getUsername(),"ABCD-2345-EFGH","a-new-password-123");var q=org.mockito.ArgumentCaptor.forClass(Query.class);var update=org.mockito.ArgumentCaptor.forClass(Update.class);verify(mongo).findAndModify(q.capture(),update.capture(),any(FindAndModifyOptions.class),eq(UserModel.class));String query=q.getValue().getQueryObject().toString();assertTrue(query.contains("enabled"));assertTrue(query.contains("accessTicket.attempts"));assertTrue(query.contains("accessTicket.expiresAt"));String mutation=update.getValue().getUpdateObject().toString();assertTrue(mutation.contains("$unset"));assertTrue(mutation.contains("accessTicket"));assertFalse(mutation.contains("roles"));assertFalse(mutation.contains("school"));assertThrows(ResponseStatusException.class,()->service.complete(user.getUsername(),"ABCD2345EFGH","a-new-password-123"));}
 @Test void wrongCredentialConsumesBoundedAttempt(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");assertThrows(ResponseStatusException.class,()->service.complete(user.getUsername(),"WRONG","a-new-password-123"));verify(mongo).updateFirst(argThat(q->q.getQueryObject().toString().contains("accessTicket.issueId")),argThat(u->u.getUpdateObject().toString().contains("-1")),eq(UserModel.class));verifyNoInteractions(encoder);}
 @Test void exhaustedAttemptsCannotComplete(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");user.getAccessTicket().setAttempts(0);assertThrows(ResponseStatusException.class,()->service.complete(user.getUsername(),"ABCD2345EFGH","a-new-password-123"));verifyNoInteractions(encoder);}
 @Test void expiredCannotComplete(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");user.getAccessTicket().setExpiresAt(Instant.now().minusSeconds(1));assertThrows(ResponseStatusException.class,()->service.complete(user.getUsername(),"ABCD2345EFGH","a-new-password-123"));}
 @Test void disabledCannotCompleteOrRequestEmail(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");user.setEnabled(false);assertThrows(ResponseStatusException.class,()->service.complete(user.getUsername(),"ABCD2345EFGH","a-new-password-123"));service.requestReset(user.getUsername());verifyNoInteractions(mail);}
 @Test void crossEnvironmentCannotComplete(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");user.getAccessTicket().setEnvironment("https://other.example.test");assertThrows(ResponseStatusException.class,()->service.complete(user.getUsername(),"ABCD2345EFGH","a-new-password-123"));verifyNoInteractions(encoder);}
 @Test void schoolCredentialCannotBeUsedAsEmailToken(){ticket("ABCD2345EFGH","SCHOOL_ASSISTED");assertThrows(ResponseStatusException.class,()->service.complete(null,"ABCD2345EFGH","a-new-password-123"));}
 @Test void existingAccountResetDoesNotRequireSetupFlag(){ticket("synthetic-email-token","PASSWORD_RESET");when(mongo.findAndModify(any(),any(),any(FindAndModifyOptions.class),eq(UserModel.class))).thenReturn(user);service.complete(null,"synthetic-email-token","a-new-password-123");verify(encoder).encode("a-new-password-123");}
 @Test void tokenIsNotSerialized(){ticket("secret","SCHOOL_ASSISTED");String json=new ObjectMapper().valueToTree(user).toString();assertFalse(json.contains("accessTicket"));assertFalse(json.contains("digest"));assertFalse(new AccountAccessService.Handoff("student","secret",Instant.now(),5).toString().contains("secret"));}
 @Test void reissueRevokesTicketAndSessions(){service.revoke(user.getId());verify(mongo).updateFirst(any(Query.class),argThat(u->u.getUpdateObject().toString().contains("credentialVersion")&&u.getUpdateObject().toString().contains("accessTicket")),eq(UserModel.class));}
 @ParameterizedTest @ValueSource(strings={"https://evil.example.test/path","https://user@example.test","https://example.test?redirect=evil","http://example.test",""}) void unsafeOriginsRejected(String url){env.setProperty("reps.accounts.public-base-url",url);assertThrows(IllegalStateException.class,service::publicBaseUrl);}
 @Test void localAllowedExceptProduction(){env.setProperty("reps.accounts.public-base-url","http://localhost:3000");assertEquals("http://localhost:3000",service.publicBaseUrl());env.setActiveProfiles("prod");assertThrows(IllegalStateException.class,service::publicBaseUrl);}
 @Test void unknownAndNonPrivateStudentEmailsHaveNoSend(){service.requestReset("unknown@example.test");user.setRoles(Set.of(new RoleModel(null,"student")));service.requestReset(user.getUsername());verifyNoInteractions(mail);}
 @Test void smtpFailureIsDurableAndRetryableWithoutLosingAccount() throws Exception {user.setPasswordSetupRequired(true);when(mongo.findAndModify(any(),any(),any(FindAndModifyOptions.class),eq(UserModel.class))).thenAnswer(i->{var u=(Update)i.getArgument(1);var set=(org.bson.Document)u.getUpdateObject().get("$set");user.setAccessTicket((UserModel.AccessTicket)set.get("accessTicket"));return user;});doThrow(new MailAuthenticationException("synthetic failure")).doNothing().when(mail).sendSystemBulkEmail(anyString(),isNull(),anyString(),anyString(),isNull(),isNull());service.createdStaff(user);verify(mongo).updateFirst(any(Query.class),argThat(u->u.getUpdateObject().toString().contains("FAILED")),eq(UserModel.class));service.createdStaff(user);verify(mongo).updateFirst(any(Query.class),argThat(u->u.getUpdateObject().toString().contains("SENT")),eq(UserModel.class));verify(users,never()).delete(any());}
 @Test void googleRequiresApprovalAndVerifiedIdentity(){user.setPasswordSetupRequired(true);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.googleEstablished(user,false));service.googleEstablished(user,true);verify(mongo).updateFirst(any(Query.class),argThat(u->u.getUpdateObject().toString().contains("GOOGLE_ESTABLISHED")),eq(UserModel.class));user.setEnabled(false);assertThrows(ResponseStatusException.class,()->service.googleEstablished(user,true));}
}
